#!/usr/bin/env python3
"""Clasificador de casos con salida estructurada (API de Anthropic).

Uso:
  python clasificador.py "texto del caso"
  python clasificador.py --fichero caso.txt
  cat caso.txt | python clasificador.py

Requisitos:
  pip install anthropic
  export ANTHROPIC_API_KEY="tu-clave"   (Windows: set ANTHROPIC_API_KEY=...)
"""

import argparse
import json
import os
import sys

try:
    import anthropic
except ImportError:
    sys.exit("Falta el SDK de Anthropic. Instálalo con: pip install anthropic")

# ── Configuración: adapta esto a tu negocio ─────────────────────────────

MODELO = "claude-haiku-4-5"  # clasificar es tarea de modelo pequeño y barato

CATEGORIAS = ["consulta", "pedido", "incidencia", "factura", "queja", "otro"]
UMBRAL_CONFIANZA = 0.7  # por debajo, el caso se marca para revisión humana
MAX_CARACTERES = 12000  # ~3.000 palabras; por encima, avisamos

SISTEMA = (
    "Eres un clasificador de casos de un negocio en español. "
    "Lee el texto y clasifícalo llamando a la herramienta. "
    "Si el texto no encaja claramente en ninguna categoría, usa 'otro' "
    "con confianza baja. El motivo debe citar palabras del propio texto."
)

# La herramienta con esquema estricto: la API garantiza que la respuesta
# valida contra este esquema. Nada de JSON roto ni campos sorpresa.
HERRAMIENTA = {
    "name": "clasificar_caso",
    "description": "Registra la clasificación del caso analizado.",
    "strict": True,
    "input_schema": {
        "type": "object",
        "properties": {
            "categoria": {"type": "string", "enum": CATEGORIAS},
            "urgencia": {"type": "string", "enum": ["alta", "media", "baja"]},
            "confianza": {
                "type": "number",
                "minimum": 0,
                "maximum": 1,
                "description": "Seguridad de la clasificación, de 0 a 1.",
            },
            "motivo": {
                "type": "string",
                "description": "Una frase citando el texto que justifica la categoría.",
            },
        },
        "required": ["categoria", "urgencia", "confianza", "motivo"],
        "additionalProperties": False,
    },
}

# ── Lógica ──────────────────────────────────────────────────────────────


def clasificar(client: "anthropic.Anthropic", texto: str) -> dict:
    """Llama a la API forzando el uso de la herramienta y devuelve el dict."""
    respuesta = client.messages.create(
        model=MODELO,
        max_tokens=512,
        system=SISTEMA,
        tools=[HERRAMIENTA],
        tool_choice={"type": "tool", "name": "clasificar_caso"},
        messages=[{"role": "user", "content": texto}],
    )
    for bloque in respuesta.content:
        if bloque.type == "tool_use" and bloque.name == "clasificar_caso":
            return dict(bloque.input)
    raise RuntimeError("La API no devolvió la clasificación esperada.")


def leer_entrada(args: argparse.Namespace) -> str:
    if args.fichero:
        try:
            with open(args.fichero, encoding="utf-8") as f:
                return f.read()
        except OSError as e:
            sys.exit(f"No puedo leer el fichero: {e}")
    if args.texto:
        return args.texto
    if not sys.stdin.isatty():
        return sys.stdin.read()
    sys.exit("Dame un texto: como argumento, con --fichero o por stdin. Mira --help.")


def main() -> None:
    parser = argparse.ArgumentParser(description="Clasifica un caso de texto libre.")
    parser.add_argument("texto", nargs="?", help="Texto del caso a clasificar")
    parser.add_argument("--fichero", help="Ruta a un fichero de texto con el caso")
    args = parser.parse_args()

    if not os.environ.get("ANTHROPIC_API_KEY"):
        sys.exit(
            "Falta la variable de entorno ANTHROPIC_API_KEY.\n"
            "Crea la clave en console.anthropic.com y expórtala antes de ejecutar."
        )

    texto = leer_entrada(args).strip()
    if not texto:
        sys.exit("El texto está vacío: no hay nada que clasificar.")
    if len(texto) > MAX_CARACTERES:
        print(
            f"AVISO: texto de {len(texto)} caracteres; se recorta a {MAX_CARACTERES}.",
            file=sys.stderr,
        )
        texto = texto[:MAX_CARACTERES]

    client = anthropic.Anthropic()  # lee ANTHROPIC_API_KEY del entorno

    try:
        resultado = clasificar(client, texto)
    except anthropic.AuthenticationError:
        sys.exit("Clave de API inválida o revocada. Revisa ANTHROPIC_API_KEY.")
    except anthropic.RateLimitError:
        sys.exit("Límite de peticiones alcanzado. Espera un minuto y reintenta.")
    except anthropic.APIStatusError as e:
        sys.exit(f"Error de la API ({e.status_code}): {e.message}")
    except anthropic.APIConnectionError:
        sys.exit("No hay conexión con la API. Revisa tu red y reintenta.")

    # Freno de confianza: lo dudoso se marca para revisión humana.
    resultado["revision_humana"] = resultado["confianza"] < UMBRAL_CONFIANZA

    print(json.dumps(resultado, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()
